from itertools import permutations

def check_close(p1, p2):
    """Checks if two permutations p1 and p2 are 'close'."""
    if len(p1) != len(p2):
        return False
    for x, y in zip(p1, p2):
        if abs(x - y) >= 2:
            return False
    return True

k = 3
perms = list(permutations(range(1, k + 1)))

# Test if N=3 is the maximum possible size for k=3
# We iterate through all subsets of size 4 to see if they exist
max_n = 0
n_size = len(perms)

for i in range(n_size):
    for j in range(i + 1, n_size):
        for l in range(j + 1, n_size):
            subset = [perms[i], perms[j], perms[l]]
            is_valid_subset = True
            # Check pairwise distances
            for a in range(3):
                for b in range(a + 1, 3):
                    if check_close(subset[a], subset[b]):
                        is_valid_subset = False
                        break
                if not is_valid_subset:
                    break

            if is_valid_subset:
                max_n = max(max_n, 3)

# Check if N=4 exists
is_4_possible = False
for combo in itertools.combinations(perms, 4):
    is_valid = True
    for i in range(4):
        for j in range(i + 1, 4):
            if check_close(combo[i], combo[j]):
                is_valid = False
                break
        if not is_valid:
            break
    if is_valid:
        is_4_possible = True
        break

print(f"N(3) is at least: {max_n}")
